def is_multiply_prime(a):
    """
    Return True if the given number is the product of exactly 3 prime numbers,
    and False otherwise. Repeated prime factors are allowed.
    """
    if a < 2:
        return False

    n = a
    prime_factor_count = 0
    divisor = 2

    while divisor * divisor <= n:
        while n % divisor == 0:
            prime_factor_count += 1
            n //= divisor

            if prime_factor_count > 3:
                return False

        divisor += 1

    if n > 1:
        prime_factor_count += 1

    return prime_factor_count == 3

