def is_simple_power(x, n):
    """
    Return True if x is a simple power of n, otherwise False.
    x is a simple power of n if n**int == x for some integer exponent.
    """
    if x == 1:
        return True

    if n == 0:
        return x == 0

    if n == 1:
        return False

    if n == -1:
        return x in (1, -1)

    if x < 0 and n > 0:
        return False

    power = 1
    while abs(power) <= abs(x):
        if power == x:
            return True
        power *= n

    return False
