def get_row(lst, x):
    """
    Find all occurrences of x in a jagged 2D list and return their coordinates.

    Coordinates are sorted by row in ascending order, and within each row
    by column in descending order.
    """
    coordinates = []

    for row_index, row in enumerate(lst):
        for col_index, value in enumerate(row):
            if value == x:
                coordinates.append((row_index, col_index))

    coordinates.sort(key=lambda coord: (coord[0], -coord[1]))
    return coordinates

